#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=6

# check_http "label" CODE: report a live key check without ever printing the key.
check_http() {
  if [[ "$2" == "200" ]]; then
    printf '  %s✓ %s works%s\n' "$GREEN" "$1" "$RESET"
  else
    warn "$1 check returned HTTP $2. Double-check the value; re-run the wizard to fix it."
  fi
}

banner "AI Gothenburg Ops Copilot · accounts and keys"

# ── 1. Command Code (all models) ──────────────────────────────────────────
stage "Command Code (all models)"
say "One Command Code key covers every model the Copilot uses:"
say "  Ling 3.0 Flash Sante (free) for development, Claude for the release gate"
say "  and the demo, GPT-6 Sol as the eval judge."
note "Needs a plan with API access (every plan except Go)."
open_url "https://commandcode.ai/settings/keys"
step "Sign in, then create an API key. Name it: gbg-ops-copilot"
step "Copy the key. The same key works for the Command Code CLI and the API."
ask_secret COMMANDCODE_API_KEY "Paste the Command Code API key:"
write_env COMMANDCODE_API_KEY "$COMMANDCODE_API_KEY"
# Free check: an empty request returns 400 (key accepted) or 401 (key rejected).
code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 -X POST \
  "https://api.commandcode.ai/provider/v1/chat/completions" \
  -H "Authorization: Bearer $COMMANDCODE_API_KEY" \
  -H "content-type: application/json" -d '{}' || true)
case "$code" in
  400|422) printf '  %s✓ Command Code key works%s\n' "$GREEN" "$RESET" ;;
  401|403) warn "Command Code rejected the key (HTTP $code). Check the key and that your plan includes API access." ;;
  *) warn "Command Code check returned HTTP $code. Re-run the wizard to retry." ;;
esac
pause

# ── 2. LangSmith ──────────────────────────────────────────────────────────
stage "LangSmith (tracing, evals, Prompt Hub)"
say "LangSmith has a US and an EU instance. EU keeps traces of (later, real)"
say "applicant emails inside the EU, which helps the GDPR story in the pitch."
if confirm "Use the EU instance? (recommended)"; then
  LS_UI="https://eu.smith.langchain.com"; LANGSMITH_ENDPOINT="https://eu.api.smith.langchain.com"
else
  LS_UI="https://smith.langchain.com";    LANGSMITH_ENDPOINT="https://api.smith.langchain.com"
fi
note "An account on one instance does not exist on the other; sign up there if needed."
open_url "$LS_UI/settings"
step "Settings → API Keys → 'Create API Key'. Description: gbg-ops-copilot"
step "Copy the key (starts with lsv2_). It is shown only once."
ask_secret LANGSMITH_API_KEY "Paste the LangSmith API key:"
write_env LANGSMITH_API_KEY "$LANGSMITH_API_KEY"
write_env LANGSMITH_ENDPOINT "$LANGSMITH_ENDPOINT"
write_env LANGSMITH_TRACING "true"
write_env LANGSMITH_PROJECT "gbg-ops-copilot"
check_http "LangSmith key" "$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
  "$LANGSMITH_ENDPOINT/api/v1/sessions?limit=1" -H "x-api-key: $LANGSMITH_API_KEY" || true)"
pause

# ── 3. Pinecone ───────────────────────────────────────────────────────────
stage "Pinecone (similarity search)"
say "Pinecone stores embeddings only; Postgres stays the source of truth."
say "The index itself is created later by code, with Pinecone's hosted model."
open_url "https://app.pinecone.io"
step "Sign in (the free Starter plan is enough). Left menu → 'API keys'."
step "Click 'Create API key'. Name it: gbg-ops-copilot. Copy the value."
ask_secret PINECONE_API_KEY "Paste the Pinecone API key:"
write_env PINECONE_API_KEY "$PINECONE_API_KEY"
write_env PINECONE_INDEX "gbg-ops-copilot"
check_http "Pinecone key" "$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
  https://api.pinecone.io/indexes -H "Api-Key: $PINECONE_API_KEY" || true)"
pause

# ── 4. Tavily ─────────────────────────────────────────────────────────────
stage "Tavily (web search for the Brief researcher)"
open_url "https://app.tavily.com/home"
step "Sign in. Your default API key is shown on the overview page."
step "Copy it (starts with tvly-)."
ask_secret TAVILY_API_KEY "Paste the Tavily API key:"
write_env TAVILY_API_KEY "$TAVILY_API_KEY"
note "Not checked live: a test search would spend one of your free credits."
pause

# ── 5. Daily Report email (optional) ──────────────────────────────────────
stage "Daily Report email (optional)"
say "Without this, the Daily Report is only saved as an HTML file (dry-run)."
say "With it, the report is emailed to you, e.g. to show on your phone in the pitch."
if confirm "Set up sending through a Gmail account now?"; then
  step "Your Google account needs 2-Step Verification turned on first."
  open_url "https://myaccount.google.com/apppasswords"
  step "App name: gbg-ops-copilot → 'Create'. Copy the 16-character password."
  ask SMTP_USER "Gmail address that sends the report:"
  ask_secret SMTP_PASSWORD "Paste the app password:"
  ask REPORT_TO "Address that receives the report (Enter = same Gmail):"
  [[ -z "$REPORT_TO" ]] && REPORT_TO="$SMTP_USER"
  write_env SMTP_HOST "smtp.gmail.com"
  write_env SMTP_PORT "587"
  write_env SMTP_USER "$SMTP_USER"
  write_env SMTP_PASSWORD "$SMTP_PASSWORD"
  write_env REPORT_TO "$REPORT_TO"
  write_env REPORT_DELIVERY "smtp"
else
  write_env REPORT_DELIVERY "dry_run"
  SKIPPED+=("Daily Report email: re-run the wizard any time to set it up")
fi
pause

# ── 6. GitHub repo + CI secrets ───────────────────────────────────────────
stage "GitHub repo and CI secrets"
say "CI needs the four API keys to run the LangSmith release gate."
say "The email password stays on this machine only; CI never sends email."
if git remote get-url origin >/dev/null 2>&1; then
  note "Using the existing remote: $(git remote get-url origin)"
elif confirm "Create a PRIVATE GitHub repo 'gbg-ops-copilot' and add it as origin?"; then
  if gh repo create gbg-ops-copilot --private --source=. --remote=origin >/dev/null; then
    printf '  %s✓ created%s private repo gbg-ops-copilot\n' "$GREEN" "$RESET"
  else
    warn "gh repo create failed; create the repo by hand, then re-run this stage."
  fi
fi
if git remote get-url origin >/dev/null 2>&1; then
  set_secret COMMANDCODE_API_KEY "$COMMANDCODE_API_KEY"
  set_secret LANGSMITH_API_KEY "$LANGSMITH_API_KEY"
  set_secret PINECONE_API_KEY "$PINECONE_API_KEY"
  set_secret TAVILY_API_KEY "$TAVILY_API_KEY"
  set_var LANGSMITH_ENDPOINT "$LANGSMITH_ENDPOINT"
else
  SKIPPED+=("GitHub repo and CI secrets: re-run the wizard once the repo exists")
fi
pause

finish
note "Next: the build starts with the fictional dataset and the triage module (/tdd)."
